function useStore(uid) {
  const [data, setData] = useState(EMPTY);
  const [loaded, setLoaded] = useState(false);
  const saveTimer = useRef(null);
  const serverV = useRef(0);   // version we last knew on the server
  const dirty = useRef(false);  // we have local edits not yet saved
  const saving = useRef(false); // a save is in flight
  const adopting = useRef(false); // we just adopted remote -> skip the save it triggers
  const dataRef = useRef(data);
  dataRef.current = data;
  const api = uid && uid !== "demo" ? API + "?u=" + encodeURIComponent(uid) : API;

  // Initial load from the shared store
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const r = await fetch(api);
        if (r.ok) {
          const remote = await r.json();
          if (alive && remote && typeof remote === "object") {
            serverV.current = remote._v || 0;
            adopting.current = true;
            setData({ ...EMPTY, ...remote });
          }
        }
      } catch (e) {
        /* no shared state yet - start fresh */
      } finally {
        if (alive) setLoaded(true);
      }
    })();
    return () => { alive = false; };
  }, []);

  // Save local changes (debounced) to the shared store
  useEffect(() => {
    if (!loaded) return;
    if (adopting.current) { adopting.current = false; return; } // don't echo a just-adopted remote
    dirty.current = true;
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(async () => {
      const v = Date.now();
      saving.current = true;
      try {
        await fetch(api, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ...data, _v: v }),
        });
        serverV.current = v;
        dirty.current = false;
      } catch (e) {
        console.error("Opslaan mislukt", e);
      } finally {
        saving.current = false;
      }
    }, 500);
  }, [data, loaded]);

  // Poll for changes made on the other device (near-live sync)
  useEffect(() => {
    if (!loaded) return;
    const id = setInterval(async () => {
      if (dirty.current || saving.current) return; // never clobber in-progress edits
      try {
        const r = await fetch(api);
        if (!r.ok) return;
        const remote = await r.json();
        if (remote && (remote._v || 0) > serverV.current) {
          serverV.current = remote._v || 0;
          adopting.current = true;
          setData({ ...EMPTY, ...remote });
        }
      } catch (e) {
        /* offline - try again next tick */
      }
    }, 12000);
    return () => clearInterval(id);
  }, [loaded]);

  // Flush immediately when leaving / hiding the page so edits aren't lost
  useEffect(() => {
    const flush = () => {
      if (!dirty.current) return;
      const payload = JSON.stringify({ ...dataRef.current, _v: Date.now() });
      try {
        if (navigator.sendBeacon) {
          navigator.sendBeacon(api, new Blob([payload], { type: "application/json" }));
        } else {
          fetch(api, { method: "POST", headers: { "Content-Type": "application/json" }, body: payload, keepalive: true });
        }
        dirty.current = false;
      } catch (e) {}
    };
    const onVis = () => { if (document.visibilityState === "hidden") flush(); };
    window.addEventListener("pagehide", flush);
    document.addEventListener("visibilitychange", onVis);
    return () => {
      window.removeEventListener("pagehide", flush);
      document.removeEventListener("visibilitychange", onVis);
      flush();
    };
  }, []);

  return { data, setData, loaded };
}

