function Tasks({ tasks, data, setData }) {
  const [ownerFilter, setOwnerFilter] = useState("Alle");
  const [catFilter, setCatFilter] = useState("Alle");
  const [hideDone, setHideDone] = useState(false);
  const [open, setOpen] = useState(null);
  const [editing, setEditing] = useState(null);
  const [adding, setAdding] = useState(false);
  const [confirmClear, setConfirmClear] = useState(false);
  const [extrasOpen, setExtrasOpen] = useState(false);
  const clearAll = () => { setData((d) => ({ ...d, customTasks: [], showDemoTasks: false, taskDone: {}, taskEdits: {}, taskRemoved: {} })); setConfirmClear(false); };

  const nameA = data.coupleA || "Partner 1";
  const nameB = data.coupleB || "Partner 2";
  const owners = [nameA, nameB, "Samen"];
  const filterOwners = ["Alle", nameA, nameB, "Samen"];
  const ownerColor = (o) => (o === nameA ? "#5b6b57" : o === nameB ? "#c1913f" : o === "Samen" ? "#b08d57" : "#9a8b7a");
  const categories = [...new Set(tasks.map((t) => t.category))].sort((a, b) => a.localeCompare(b, "nl"));

  const toggleDone = (id) =>
    setData((d) => ({ ...d, taskDone: { ...d.taskDone, [id]: !d.taskDone[id] } }));

  const postFor = (id) => data.posten.find((p) => p.taskId === id);
  const setTaskBudget = (task, amount) =>
    setData((d) => {
      if (amount == null) return { ...d, posten: d.posten.filter((p) => p.taskId !== task.id) };
      const exists = d.posten.some((p) => p.taskId === task.id);
      if (exists) return { ...d, posten: d.posten.map((p) => (p.taskId === task.id ? { ...p, amount } : p)) };
      return { ...d, posten: [...d.posten, { id: "tb" + Date.now(), name: task.name, amount, taskId: task.id }] };
    });

  const editTask = (id, field, value) =>
    setData((d) => ({ ...d, taskEdits: { ...d.taskEdits, [id]: { ...(d.taskEdits[id] || {}), [field]: value } } }));
  const removeTask = (id) =>
    setData((d) => ({
      ...d,
      customTasks: id.startsWith("c") ? d.customTasks.filter((t) => t.id !== id) : d.customTasks,
      taskRemoved: id.startsWith("c") ? d.taskRemoved : { ...d.taskRemoved, [id]: true },
      taskEdits: Object.fromEntries(Object.entries(d.taskEdits).filter(([k]) => k !== id)),
      posten: d.posten.filter((p) => p.taskId !== id),
    }));

  const editingTask = editing ? tasks.find((t) => t.id === editing) : null;
  const filtered = tasks.filter((t) => {
    if (ownerFilter !== "Alle" && t.owner !== ownerFilter) return false;
    if (catFilter !== "Alle" && t.category !== catFilter) return false;
    if (hideDone && data.taskDone[t.id]) return false;
    return true;
  });

  // Group tasks by the Sunday meeting they fall before.
  const groups = {};
  filtered.forEach((t) => {
    const b = besprekingFor(t.deadline);
    (groups[b] ||= []).push(t);
  });
  const groupKeys = Object.keys(groups).sort();
  groupKeys.forEach((k) => groups[k].sort((a, b) => a.deadline.localeCompare(b.deadline)));

  return (
    <div className="wp-stack">
      <div className="wp-filterbar">
        <div className="wp-filterrow-plain">
          <FilterSelect
            label="Naam"
            value={ownerFilter}
            options={[["Alle", "Alle namen"], [nameA, nameA], [nameB, nameB], ["Samen", "Samen"]]}
            onChange={setOwnerFilter}
          />
          <FilterSelect
            label="Categorie"
            value={catFilter}
            options={[["Alle", "Alle categorieën"], ...categories.map((c) => [c, c])]}
            onChange={setCatFilter}
          />
          <div className="wp-fsel">
            <button className={"wp-fsel-btn" + (extrasOpen ? " is-open" : "")} onClick={() => setExtrasOpen((o) => !o)} aria-haspopup="menu" aria-expanded={extrasOpen}>
              <span className="wp-fsel-lab">Overige</span>
              <span className="wp-fsel-val">Opties</span>
              <span className="wp-fsel-chev" aria-hidden="true">›</span>
            </button>
            {extrasOpen && (
              <>
                <div className="wp-fsel-backdrop" onClick={() => { setExtrasOpen(false); setConfirmClear(false); }} />
                <div className="wp-fsel-menu wp-extras-menu" role="menu">
                  <button className="wp-fsel-opt" onClick={() => setHideDone((v) => !v)}>
                    <span>Verberg afgevinkt</span>
                    {hideDone && <span className="wp-fsel-tick" aria-hidden="true">✓</span>}
                  </button>
                  <button className="wp-fsel-opt" onClick={() => setData((d) => ({ ...d, showDemoTasks: !d.showDemoTasks }))}>
                    <span>Demo-taken tonen</span>
                    {data.showDemoTasks && <span className="wp-fsel-tick" aria-hidden="true">✓</span>}
                  </button>
                  {tasks.length > 0 && (confirmClear ? (
                    <div className="wp-extras-danger">
                      <span>Hele lijst legen?</span>
                      <div className="wp-extras-danger-row">
                        <button className="wp-btn-ghost" onClick={() => setConfirmClear(false)}>Annuleren</button>
                        <button className="wp-btn-danger" onClick={() => { clearAll(); setExtrasOpen(false); }}>Legen</button>
                      </div>
                    </div>
                  ) : (
                    <button className="wp-fsel-opt wp-extras-del" onClick={() => setConfirmClear(true)}>Hele lijst verwijderen</button>
                  ))}
                </div>
              </>
            )}
          </div>
        </div>
      </div>

      {groupKeys.map((sunday) => {
        const d = daysUntil(sunday);
        const rel = d < 0 ? "geweest" : d === 0 ? "vandaag" : d === 1 ? "morgen" : `over ${d} dagen`;
        const mi = MEETINGS.indexOf(sunday);
        const weekStart = mi > 0 ? addDaysISO(MEETINGS[mi - 1], 1) : addDaysISO(sunday, -6);
        const openCount = groups[sunday].filter((t) => !data.taskDone[t.id]).length;
        return (
          <section key={sunday} className="wp-card wp-task-group">
            <div className="wp-group-head">
              <div>
                <h3 className="wp-group-date">Vóór bespreking {longDate(sunday)}</h3>
                <span className="wp-group-range">{shortDate(weekStart)} tot {shortDate(sunday)} · {openCount} open</span>
              </div>
              <span className={"wp-group-meta" + (d < 0 ? " is-over" : "")}>{rel}</span>
            </div>
            <ul className="wp-task-list">
              {groups[sunday].map((t) => {
                const isDone = !!data.taskDone[t.id];
                const isOpen = open === t.id;
                const over = !isDone && daysUntil(t.deadline) < 0;
                return (
                  <li key={t.id} className={"wp-task" + (isDone ? " is-done" : "")}>
                    <button className={"wp-check" + (isDone ? " is-on" : "")} onClick={() => toggleDone(t.id)} aria-label={isDone ? "Markeer als niet gedaan" : "Markeer als gedaan"}>
                      {isDone && <Check />}
                    </button>
                    <div className="wp-task-body" onClick={() => { if (isOpen) { setOpen(null); setEditing(null); } else { setOpen(t.id); } }}>
                      <span className="wp-task-name">{t.name}</span>
                      <div className="wp-task-meta">
                        <span className="wp-tag" style={{ color: catColor(t.category), borderColor: catColor(t.category) + "55" }}>{t.category}</span>
                        <span className="wp-owner" style={{ background: ownerColor(t.owner) + "22", color: ownerColor(t.owner) }}>{t.owner}</span>
                        <span className="wp-tb-wrap" onClick={(e) => e.stopPropagation()}>
                          <EditableAmount
                            small
                            value={(() => { const p = postFor(t.id); return p && p.amount > 0 ? p.amount : null; })()}
                            emptyLabel="+ budget"
                            allowClear
                            onSave={(n) => setTaskBudget(t, n)}
                          />
                        </span>
                      </div>
                      {isOpen && (
                        <div className="wp-task-fold" onClick={(e) => e.stopPropagation()}>
                          {t.details ? <p className="wp-task-detail">{t.details}</p> : <p className="wp-task-detail is-empty">Nog geen omschrijving</p>}
                          <button className="wp-edit-btn" onClick={() => setEditing(t.id)} aria-label="Taak bewerken">✎ bewerk</button>
                        </div>
                      )}
                    </div>
                    <span className={"wp-task-date" + (over ? " is-over" : "")} title={longDate(t.deadline)}>{shortDate(t.deadline)}</span>
                  </li>
                );
              })}
            </ul>
          </section>
        );
      })}

      {adding ? (
        <AddTask
          owners={owners}
          onAdd={(task) => {
            setData((d) => ({ ...d, customTasks: [...d.customTasks, { ...task, id: "c" + Date.now() }] }));
            setAdding(false);
          }}
          onCancel={() => setAdding(false)}
        />
      ) : (
        <button className="wp-add-btn" onClick={() => setAdding(true)}>+ Taak toevoegen</button>
      )}

      {editingTask && (
        <div className="wp-modal-back" onClick={() => setEditing(null)}>
          <div className="wp-modal" onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true">
            <div className="wp-modal-head">
              <span className="wp-modal-title">Taak bewerken</span>
              <button className="wp-modal-x" onClick={() => setEditing(null)} aria-label="Sluiten">×</button>
            </div>
            <label className="wp-te-lab">Naam</label>
            <input className="wp-te-input" value={editingTask.name} placeholder="Taaknaam" onChange={(e) => editTask(editingTask.id, "name", e.target.value)} />
            <label className="wp-te-lab">Omschrijving</label>
            <input className="wp-te-input" value={editingTask.details || ""} placeholder="Korte omschrijving in één zin" onChange={(e) => editTask(editingTask.id, "details", e.target.value)} />
            <label className="wp-te-lab">Wie</label>
            <div className="wp-te-seg wp-te-seg-full">
              {owners.map((o) => (
                <button key={o} type="button" className={"wp-te-segbtn" + (editingTask.owner === o ? " is-on" : "")} onClick={() => editTask(editingTask.id, "owner", o)}>{o}</button>
              ))}
            </div>
            <label className="wp-te-lab">Datum</label>
            <input className="wp-te-input" type="date" value={editingTask.deadline} onChange={(e) => editTask(editingTask.id, "deadline", e.target.value)} />
            <div className="wp-te-actions">
              <button className="wp-te-del" onClick={() => { removeTask(editingTask.id); setEditing(null); }}>Verwijderen</button>
              <button className="wp-te-done" onClick={() => setEditing(null)}>Klaar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

