/* ---------- Budget ---------- */

function sibizLines(data) {
  return [...BUDGET, ...(data.sibizCustom || [])].map((b) => ({
    ...b,
    amount: data.sibizOverrides && data.sibizOverrides[b.id] != null ? data.sibizOverrides[b.id] : b.amount,
  }));
}

function budgetTotals(data) {
  const sib = sibizLines(data).reduce((s, b) => s + (b.amount || 0), 0);
  const sibPaid = Math.min(data.sibizPaid || 0, sib);
  const overige = (data.posten || []).reduce((s, p) => s + (p.amount || 0), 0);
  const offGroups = data.offertes || [];
  const off = offGroups.reduce((s, g) => s + g.lines.reduce((x, l) => x + (l.amount || 0), 0), 0);
  const offPaid = offGroups.reduce((s, g) => s + (g.lines.reduce((x, l) => x + (l.amount || 0), 0) * (g.paidPct || 0)) / 100, 0);
  const grand = sib + overige + off;
  const budget = data.budget || 0;
  return {
    sib,
    sibPaid,
    overige,
    off,
    offPaid,
    grand,
    paid: sibPaid + offPaid,
    budget,
    room: budget - grand,
  };
}

/* Reusable inline amount editor. onSave(null) means "cleared". */
function EditableAmount({ value, onSave, allowClear, emptyLabel, small }) {
  const [editing, setEditing] = useState(false);
  const [v, setV] = useState("");
  const commit = () => {
    const raw = v.trim();
    if (raw === "") {
      if (allowClear) onSave(null);
      setEditing(false);
      return;
    }
    let s = raw.replace(/\s/g, "");
    s = s.includes(",") ? s.replace(/\./g, "").replace(",", ".") : s;
    const n = parseFloat(s);
    onSave(isNaN(n) ? (allowClear ? null : value) : n);
    setEditing(false);
  };
  if (editing) {
    return (
      <input
        className={small ? "wp-tb-input" : "wp-amt-input"}
        type="text"
        inputMode="decimal"
        autoFocus
        value={v}
        onChange={(e) => setV(e.target.value)}
        onBlur={commit}
        onKeyDown={(e) => {
          if (e.key === "Enter") commit();
          if (e.key === "Escape") setEditing(false);
        }}
      />
    );
  }
  const empty = value == null;
  const cls = small ? (empty ? "wp-tb-add" : "wp-tb-pill") : empty ? "wp-amt is-empty" : "wp-amt";
  const label = empty ? emptyLabel || "+ bedrag" : small ? euro0(value) : euro(value);
  return (
    <button
      className={cls}
      onClick={() => {
        setV(value != null ? String(value) : "");
        setEditing(true);
      }}
    >
      {label}
    </button>
  );
}

/* Inline editable text (single or multi-line). Tap to edit, blur/Enter to save. */
function EditableText({ value, onSave, className, multiline, placeholder }) {
  const [editing, setEditing] = useState(false);
  const [v, setV] = useState(value);
  const commit = () => { onSave((v || "").trim() || value); setEditing(false); };
  if (editing) {
    const common = {
      autoFocus: true,
      value: v,
      placeholder,
      onChange: (e) => setV(e.target.value),
      onBlur: commit,
      className: "wp-textedit",
    };
    return multiline ? (
      <textarea rows={2} {...common} onKeyDown={(e) => { if (e.key === "Escape") setEditing(false); }} />
    ) : (
      <input type="text" {...common} onKeyDown={(e) => { if (e.key === "Enter") commit(); if (e.key === "Escape") setEditing(false); }} />
    );
  }
  return (
    <span className={(className || "") + " wp-editable"} onClick={() => { setV(value); setEditing(true); }}>
      {value}
    </span>
  );
}

function InlineAdd({ placeholder, withCategory, categories, onAdd, onCancel }) {
  const [name, setName] = useState("");
  const [cat, setCat] = useState(categories ? categories[0] : "");
  return (
    <div className="wp-card wp-addform" style={{ marginTop: 10 }}>
      <input className="wp-input" placeholder={placeholder} value={name} onChange={(e) => setName(e.target.value)} />
      {withCategory && (
        <select className="wp-input" value={cat} onChange={(e) => setCat(e.target.value)}>
          {categories.map((c) => <option key={c}>{c}</option>)}
        </select>
      )}
      <div className="wp-addrow">
        <button className="wp-btn-ghost" onClick={onCancel}>Annuleren</button>
        <button className="wp-btn" disabled={!name.trim()} onClick={() => onAdd(name.trim(), cat)}>Toevoegen</button>
      </div>
    </div>
  );
}

/* Foldout card - header always visible (shows status), body folds. */
function Collapsible({ title, badge, badgeClass, status, total, accent, defaultOpen, flush, section, children }) {
  const [open, setOpen] = useState(!!defaultOpen);
  return (
    <section className={"wp-fold " + (flush ? "wp-fold-flush" : section ? "wp-card wp-fold-section" : "wp-card") + (accent ? " is-over" : "")}>
      <button className="wp-fold-head" aria-expanded={open} onClick={() => setOpen((o) => !o)}>
        <span className="wp-fold-main">
          <span className="wp-fold-titlerow">
            <span className="wp-fold-name">{title}</span>
            {badge && <span className={"wp-badge " + badgeClass}>{badge}</span>}
          </span>
          {status && <span className="wp-fold-status">{status}</span>}
        </span>
        <span className="wp-fold-right">
          {section ? (
            <span className="wp-fold-stotal">
              <span className="wp-fold-stotal-lab">totaal</span>
              <span className="wp-fold-stotal-num">{total}</span>
            </span>
          ) : (
            <span className={"wp-subtotal" + (flush ? " wp-subtotal-sub" : "")}>{total}</span>
          )}
          <span className={"wp-chev" + (open ? " is-open" : "")} aria-hidden="true">›</span>
        </span>
      </button>
      {open && <div className="wp-fold-body">{children}</div>}
    </section>
  );
}

/* Clean custom dropdown for filters (no native select, no scrollbar row). */
function FilterSelect({ label, value, options, onChange }) {
  const [open, setOpen] = useState(false);
  const current = options.find((o) => o[0] === value);
  return (
    <div className="wp-fsel">
      <button className={"wp-fsel-btn" + (open ? " is-open" : "") + (value !== options[0][0] ? " is-set" : "")} onClick={() => setOpen((o) => !o)} aria-haspopup="listbox" aria-expanded={open}>
        <span className="wp-fsel-lab">{label}</span>
        <span className="wp-fsel-val">{current ? current[1] : value}</span>
        <span className="wp-fsel-chev" aria-hidden="true">›</span>
      </button>
      {open && (
        <>
          <div className="wp-fsel-backdrop" onClick={() => setOpen(false)} />
          <div className="wp-fsel-menu" role="listbox">
            {options.map(([v, l]) => (
              <button
                key={v}
                role="option"
                aria-selected={v === value}
                className={"wp-fsel-opt" + (v === value ? " is-on" : "")}
                onClick={() => { onChange(v); setOpen(false); }}
              >
                <span>{l}</span>
                {v === value && <span className="wp-fsel-tick" aria-hidden="true">✓</span>}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

/* ---------- Schema ---------- */

const PHASE_COLOR = {
  "Voorbereiding": "#c1913f",
  "Pickup en inloop kerk": "#a9745f",
  "Huwelijksmis": "#8a6d3b",
  "Verplaatsing naar Vreeland": "#9a8b7a",
  "Receptie": "#5b6b57",
  "Diner": "#9c7529",
  "Feest": "#8a5a7a",
};

function Schema({ data, setData }) {
  const [role, setRole] = useState("alles");
  const [edit, setEdit] = useState(false);

  const setRow = (pi, rowId, field, value) =>
    setData((d) => ({
      ...d,
      schedule: d.schedule.map((blk, i) =>
        i !== pi ? blk : { ...blk, rows: blk.rows.map((r) => (r.id === rowId ? { ...r, [field]: value } : r)) }
      ),
    }));
  const addRow = (pi) =>
    setData((d) => ({
      ...d,
      schedule: d.schedule.map((blk, i) =>
        i !== pi ? blk : { ...blk, rows: [...blk.rows, { id: "sx" + Date.now(), time: "00:00", what: "Nieuw onderdeel", travel: null, roles: [] }] }
      ),
    }));
  const delRow = (pi, rowId) =>
    setData((d) => ({
      ...d,
      schedule: d.schedule.map((blk, i) => (i !== pi ? blk : { ...blk, rows: blk.rows.filter((r) => r.id !== rowId) })),
    }));
  const setVendor = (id, field, value) =>
    setData((d) => ({ ...d, vendors: d.vendors.map((v) => (v.id === id ? { ...v, [field]: value } : v)) }));

  const sched = data.schedule || [];
  const lastTime = sched.length ? sched[sched.length - 1].rows.slice(-1)[0]?.time : "";
  const firstTime = sched.length ? sched[0].rows[0]?.time : "";

  return (
    <div className="wp-stack">
      <div className="wp-filterbar">
        <div className="wp-filterrow-plain">
          <FilterSelect label="Rol" value={role} options={ROLE_FILTERS} onChange={setRole} />
          <button className={"wp-chip wp-chip-toggle" + (edit ? " is-on" : "")} onClick={() => setEdit((v) => !v)}>
            {edit ? "Klaar met bewerken" : "Tijden bewerken"}
          </button>
        </div>
      </div>

      <Collapsible title="Dagschema" status={role === "alles" ? "Tik tijd of tekst om te wijzigen" : "Gefilterd op " + ROLE_LABEL[role]} total={firstTime + " tot " + lastTime} defaultOpen={false}>
        <div className="wp-sched">
          {sched.map((blk, pi) => {
            const c = PHASE_COLOR[blk.phase] || "#9a8b7a";
            const rows = blk.rows
              .filter((r) => rowMatchesRole(r.roles, role))
              .slice()
              .sort((a, b) => a.time.localeCompare(b.time));
            if (rows.length === 0) return null;
            return (
              <div key={blk.phase} className="wp-sched-phase">
                <div className="wp-sched-phasehead" style={{ color: c }}>
                  <span className="wp-sched-dot" style={{ background: c }} />
                  {blk.phase}
                </div>
                {rows.map((r) => (
                  <div key={r.id} className="wp-sched-row">
                    {edit ? (
                      <input className="wp-sched-timeedit" type="time" value={r.time} onChange={(e) => setRow(pi, r.id, "time", e.target.value)} />
                    ) : (
                      <span className="wp-sched-time">{r.time}</span>
                    )}
                    <span className="wp-sched-body">
                      {edit ? (
                        <EditableText value={r.what} onSave={(v) => setRow(pi, r.id, "what", v)} className="wp-sched-what" />
                      ) : (
                        <span className="wp-sched-what">{r.what}</span>
                      )}
                      <span className="wp-sched-markers">
                        {edit ? (
                          <span className="wp-mk wp-mk-travel">reistijd:&nbsp;
                            <input className="wp-mk-input" type="number" min="0" placeholder="-" value={r.travel ?? ""} onChange={(e) => setRow(pi, r.id, "travel", e.target.value === "" ? null : Number(e.target.value))} />&nbsp;min
                          </span>
                        ) : (
                          r.travel != null && <span className="wp-mk wp-mk-travel">reistijd: {r.travel} min</span>
                        )}
                        {r.roles.length > 0 && (
                          <span className="wp-mk wp-mk-people">👤 {r.roles.map((rk) => ROLE_LABEL[rk] || rk).join(", ")}</span>
                        )}
                      </span>
                    </span>
                    {edit && <button className="wp-delx" onClick={() => delRow(pi, r.id)} aria-label="Verwijder regel">×</button>}
                  </div>
                ))}
                {edit && role === "alles" && <button className="wp-add-sm" onClick={() => addRow(pi)}>+ Regel in {blk.phase}</button>}
              </div>
            );
          })}
        </div>
      </Collapsible>

      <Collapsible title="Leveranciers" status="Aankomst en eindtijd" total={String((data.vendors || []).length)} defaultOpen={false}>
        <div className="wp-vend">
          {(data.vendors || []).map((v) => (
            <div key={v.id} className="wp-vend-row">
              <div className="wp-vend-top">
                <span className="wp-vend-name">{v.naam}</span>
                <span className="wp-vend-when">
                  {edit ? (
                    <span className="wp-row-r">
                      <input className="wp-mk-input" type="time" value={v.arrive} onChange={(e) => setVendor(v.id, "arrive", e.target.value)} />
                      <span>tot</span>
                      <input className="wp-mk-input" type="time" value={v.finish} onChange={(e) => setVendor(v.id, "finish", e.target.value)} />
                    </span>
                  ) : (
                    v.arrive + " tot " + v.finish
                  )}
                </span>
              </div>
              {edit ? (
                <EditableText value={v.desc} onSave={(val) => setVendor(v.id, "desc", val)} className="wp-vend-rol" multiline />
              ) : (
                <p className="wp-vend-rol">{v.desc}</p>
              )}
            </div>
          ))}
        </div>
      </Collapsible>
    </div>
  );
}

function Budget({ data, setData }) {
  const t = budgetTotals(data);
  const [editBudget, setEditBudget] = useState(false);
  const [bVal, setBVal] = useState(String(data.budget));
  const [editPaid, setEditPaid] = useState(false);
  const [pVal, setPVal] = useState(String(data.sibizPaid));
  const [addSibiz, setAddSibiz] = useState(false);
  const [addPost, setAddPost] = useState(false);
  const [addOfferte, setAddOfferte] = useState(false);
  const [addLineFor, setAddLineFor] = useState(null);

  const sLines = sibizLines(data);
  const catOrder = ["Receptie", "Diner", "Feest", "Organisatie & locatie", "Overig"];
  const sGroups = {};
  sLines.forEach((b) => (sGroups[b.category] ||= []).push(b));
  const sCats = Object.keys(sGroups).sort((a, b) => ((catOrder.indexOf(a) + 1) || 99) - ((catOrder.indexOf(b) + 1) || 99));

  const setSibizAmount = (id, amount) =>
    setData((d) => {
      const isCustom = d.sibizCustom.some((c) => c.id === id);
      if (amount == null) return isCustom ? { ...d, sibizCustom: d.sibizCustom.filter((c) => c.id !== id) } : d;
      if (isCustom) return { ...d, sibizCustom: d.sibizCustom.map((c) => (c.id === id ? { ...c, amount } : c)) };
      return { ...d, sibizOverrides: { ...d.sibizOverrides, [id]: amount } };
    });
  const setPostAmount = (id, amount) =>
    setData((d) => ({ ...d, posten: d.posten.map((p) => (p.id === id ? { ...p, amount: amount == null ? 0 : amount } : p)) }));
  const removePost = (id) => setData((d) => ({ ...d, posten: d.posten.filter((p) => p.id !== id) }));
  const addPostItem = (name) => setData((d) => ({ ...d, posten: [...d.posten, { id: "pn" + Date.now(), name, amount: 0 }] }));
  const addSibizItem = (name, category) => setData((d) => ({ ...d, sibizCustom: [...d.sibizCustom, { id: "sc" + Date.now(), name, category: category || "Overig", amount: 0 }] }));
  const addOfferteGroup = (name) => setData((d) => ({ ...d, offertes: [...d.offertes, { id: "of" + Date.now(), name, paidPct: 0, lines: [] }] }));
  const removeOfferte = (gid) => setData((d) => ({ ...d, offertes: d.offertes.filter((g) => g.id !== gid) }));
  const setOfferteLine = (gid, lid, amount) =>
    setData((d) => ({
      ...d,
      offertes: d.offertes.map((g) =>
        g.id !== gid ? g : { ...g, lines: amount == null ? g.lines.filter((l) => l.id !== lid) : g.lines.map((l) => (l.id === lid ? { ...l, amount } : l)) }
      ),
    }));
  const addOfferteLine = (gid, name) => setData((d) => ({ ...d, offertes: d.offertes.map((g) => (g.id !== gid ? g : { ...g, lines: [...g.lines, { id: "ol" + Date.now(), name, amount: 0 }] })) }));
  const setOffertePct = (gid, pct) => setData((d) => ({ ...d, offertes: d.offertes.map((g) => (g.id === gid ? { ...g, paidPct: pct } : g)) }));

  const sibFill = t.sib ? Math.min(t.sibPaid / t.sib, 1) : 0;
  const budFill = t.budget ? Math.min(t.grand / t.budget, 1) : 0;

  const confirmPost = (id) => setData((d) => ({ ...d, posten: d.posten.map((p) => (p.id === id ? { ...p, confirmed: true } : p)) }));
  const unconfirmPost = (id) => setData((d) => ({ ...d, posten: d.posten.map((p) => (p.id === id ? { ...p, confirmed: false } : p)) }));

  const begroting = data.posten.filter((p) => !p.confirmed);
  const bevestigd = data.posten.filter((p) => p.confirmed);
  const begrotingSum = begroting.reduce((s, p) => s + (p.amount || 0), 0);
  const bevestigdSum = bevestigd.reduce((s, p) => s + (p.amount || 0), 0);
  const offertesTotal = t.sib + t.off + bevestigdSum;
  const begrootCount = begroting.filter((p) => p.amount > 0).length;

  return (
    <div className="wp-stack">
      {/* Status bar - totals across all offertes */}
      <section className="wp-card wp-budget-hero">
        <div className="wp-bud-top">
          {editBudget ? (
            <span className="wp-row-r">budget&nbsp;<input className="wp-tb-input" type="number" autoFocus value={bVal} onChange={(e) => setBVal(e.target.value)} onBlur={() => { const v = parseFloat(bVal); if (!isNaN(v)) setData((d) => ({ ...d, budget: v })); setEditBudget(false); }} onKeyDown={(e) => e.key === "Enter" && e.currentTarget.blur()} /></span>
          ) : (
            <button className="wp-paid-pill" onClick={() => { setBVal(String(data.budget)); setEditBudget(true); }}>budget {euro0(t.budget)} ✎</button>
          )}
          <span className="wp-bud-room" style={{ color: t.room >= 0 ? "#5b6b57" : "#9c7529" }}>
            {t.room >= 0 ? `${euro0(t.room)} ruimte` : `${euro0(-t.room)} over budget`}
          </span>
        </div>
        <div className="wp-bar"><div className="wp-bar-fill" style={{ width: budFill * 100 + "%", background: t.room >= 0 ? "#5b6b57" : "#9c7529" }} /></div>
        <div className="wp-summary-3">
          <div className="wp-sum-cell">
            <span className="wp-sum-num">{euro0(t.grand)}</span>
            <span className="wp-sum-lab">totale kosten</span>
          </div>
          <div className="wp-sum-cell">
            <span className="wp-sum-num" style={{ color: "#5b6b57" }}>{euro0(t.paid)}</span>
            <span className="wp-sum-lab">aanbetaald</span>
          </div>
          <div className="wp-sum-cell">
            <span className="wp-sum-num" style={{ color: "#9c7529" }}>{euro0(t.grand - t.paid)}</span>
            <span className="wp-sum-lab">openstaand</span>
          </div>
        </div>
      </section>

      {/* ===== OFFERTES (definitieve kosten) ===== */}
      <Collapsible title="Offertes" badge="Definitieve kosten" badgeClass="wp-badge-offerte" total={euro(offertesTotal)} status="Bevestigde offertes en kosten" section defaultOpen>
      {/* Extra offertes binnen Offertes */}
      {data.offertes.map((g) => {
        const gTotal = g.lines.reduce((s, l) => s + (l.amount || 0), 0);
        return (
          <Collapsible
            flush
            key={g.id}
            title={g.name}
            badge="Offerte"
            badgeClass="wp-badge-offerte"
            total={euro(gTotal)}
            status={`${g.paidPct || 0}% aanbetaald · ${g.lines.length} ${g.lines.length === 1 ? "regel" : "regels"}`}
          >
            <div className="wp-paid">
              <OffertePaid pct={g.paidPct} onSave={(v) => setOffertePct(g.id, v)} />
              <span><b>{euro((gTotal * (g.paidPct || 0)) / 100)}</b> voldaan</span>
              <button className="wp-delx" style={{ marginLeft: "auto" }} onClick={() => removeOfferte(g.id)} aria-label="Verwijder offerte">verwijder ×</button>
            </div>
            <ul className="wp-budget-list">
              {g.lines.map((l) => (
                <li key={l.id} className="wp-budget-row">
                  <span className="wp-budget-name">{l.name}</span>
                  <span className="wp-row-r">
                    <EditableAmount value={l.amount > 0 ? l.amount : null} emptyLabel="te begroten" allowClear onSave={(n) => setOfferteLine(g.id, l.id, n)} />
                    <button className="wp-delx" onClick={() => setOfferteLine(g.id, l.id, null)} aria-label="Verwijder regel">×</button>
                  </span>
                </li>
              ))}
              {g.lines.length === 0 && <li className="wp-empty">Nog geen regels.</li>}
            </ul>
            {addLineFor === g.id ? (
              <InlineAdd placeholder="Naam regel" onAdd={(name) => { addOfferteLine(g.id, name); setAddLineFor(null); }} onCancel={() => setAddLineFor(null)} />
            ) : (
              <button className="wp-add-sm" onClick={() => setAddLineFor(g.id)}>+ Regel toevoegen</button>
            )}
          </Collapsible>
        );
      })}

      {bevestigd.length > 0 && (
        <div className="wp-confirmed-block">
          <div className="wp-subhead"><span>Bevestigde posten</span><span>{euro(bevestigdSum)}</span></div>
          <ul className="wp-budget-list">
            {bevestigd.map((p) => (
              <li key={p.id} className="wp-budget-row">
                <span className="wp-budget-name">{p.name}{p.taskId && <span className="wp-tasklink">taak</span>}</span>
                <span className="wp-row-r">
                  <EditableAmount value={p.amount > 0 ? p.amount : null} emptyLabel="te begroten" allowClear onSave={(n) => setPostAmount(p.id, n)} />
                  <button className="wp-confirm-btn is-undo" title="Terug naar begroting" aria-label="Terug naar begroting" onClick={() => unconfirmPost(p.id)}>↩</button>
                  <button className="wp-delx" onClick={() => removePost(p.id)} aria-label="Verwijder post">×</button>
                </span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {addOfferte ? (
        <InlineAdd placeholder="Naam offerte (bijv. Fotograaf, Studio X)" onAdd={(name) => { addOfferteGroup(name); setAddOfferte(false); }} onCancel={() => setAddOfferte(false)} />
      ) : (
        <button className="wp-add-sm" onClick={() => setAddOfferte(true)}>+ Nieuwe offerte</button>
      )}
      </Collapsible>

      {/* ===== BEGROTING (schattingen) ===== */}
      <Collapsible title="Begroting" badge="Schattingen" badgeClass="wp-badge-budget" total={euro(begrotingSum)} status={`${begrootCount}/${begroting.length} begroot · ✓ maakt er een offerte van`} section defaultOpen>
        <ul className="wp-budget-list">
          {begroting.map((p) => (
            <li key={p.id} className="wp-budget-row">
              <span className="wp-budget-name">{p.name}{p.taskId && <span className="wp-tasklink">taak</span>}</span>
              <span className="wp-row-r">
                <EditableAmount value={p.amount > 0 ? p.amount : null} emptyLabel="te begroten" allowClear onSave={(n) => setPostAmount(p.id, n)} />
                <button className="wp-confirm-btn" title="Bevestig als offerte" aria-label="Bevestig als offerte" onClick={() => confirmPost(p.id)} disabled={!(p.amount > 0)}>✓</button>
                <button className="wp-delx" onClick={() => removePost(p.id)} aria-label="Verwijder post">×</button>
              </span>
            </li>
          ))}
        </ul>
        {addPost ? (
          <InlineAdd placeholder="Naam kostenpost (bijv. Fotograaf)" onAdd={(name) => { addPostItem(name); setAddPost(false); }} onCancel={() => setAddPost(false)} />
        ) : (
          <button className="wp-add-sm" onClick={() => setAddPost(true)}>+ Kostenpost toevoegen</button>
        )}
      </Collapsible>
    </div>
  );
}

function OffertePaid({ pct, onSave }) {
  const [editing, setEditing] = useState(false);
  const [v, setV] = useState(String(pct || 0));
  if (editing)
    return (
      <span className="wp-row-r">
        aanbetaald&nbsp;
        <input className="wp-tb-input" type="number" autoFocus value={v} onChange={(e) => setV(e.target.value)} onBlur={() => { const n = parseFloat(v); onSave(isNaN(n) ? 0 : Math.max(0, Math.min(100, n))); setEditing(false); }} onKeyDown={(e) => e.key === "Enter" && e.currentTarget.blur()} />%
      </span>
    );
  return <button className="wp-paid-pill" onClick={() => { setV(String(pct || 0)); setEditing(true); }}>{pct || 0}% aanbetaald ✎</button>;
}

/* ---------- Guests ---------- */

const CAT_ORDER = ["Familie", "Vrienden", "Collega's", "Vrienden van ouders", "Overig", "Back-up"];

function Guests({ guests, data, setData }) {
  const [adding, setAdding] = useState(false);
  const [name, setName] = useState("");
  const [cat, setCat] = useState("Vrienden");
  const [side, setSide] = useState("Nick");

  // effective marks: stored override wins over the document's seeded value
  const inv = (g) => (data.guestInv[g.id] !== undefined ? data.guestInv[g.id] : !!g.inv);
  const pres = (g) => (data.guestPres[g.id] !== undefined ? data.guestPres[g.id] : !!g.pres);
  const toggleInv = (g) => setData((d) => ({ ...d, guestInv: { ...d.guestInv, [g.id]: !(d.guestInv[g.id] !== undefined ? d.guestInv[g.id] : !!g.inv) } }));
  const togglePres = (g) => setData((d) => ({ ...d, guestPres: { ...d.guestPres, [g.id]: !(d.guestPres[g.id] !== undefined ? d.guestPres[g.id] : !!g.pres) } }));

  const invited = guests.filter(inv).length;
  const present = guests.filter(pres).length;

  const sides = [data.coupleA || "Partner 1", data.coupleB || "Partner 2"];

  return (
    <div className="wp-stack">
      <section className="wp-card wp-guest-summary">
        <div className="wp-gs-cell"><span className="wp-gs-num" style={{ color: "#b08d57" }}>{invited}</span><span className="wp-gs-lab">uitgenodigd</span></div>
        <div className="wp-gs-cell"><span className="wp-gs-num" style={{ color: "#5b6b57" }}>{present}</span><span className="wp-gs-lab">aanwezig</span></div>
        <div className="wp-gs-cell"><span className="wp-gs-num">{guests.length}</span><span className="wp-gs-lab">op de lijst</span></div>
      </section>

      {sides.map((s) => {
        const sideGuests = guests.filter((g) => (g.side || "Nick") === s);
        const sInvited = sideGuests.filter(inv).length;
        const sPresent = sideGuests.filter(pres).length;
        const cats = {};
        sideGuests.forEach((g) => (cats[g.category] ||= []).push(g));
        const sortedCats = Object.keys(cats).sort((a, b) => ((CAT_ORDER.indexOf(a) + 1) || 99) - ((CAT_ORDER.indexOf(b) + 1) || 99));
        return (
          <Collapsible
            key={s}
            title={s === "Nick" ? "Bruidegom · Nick" : "Bruid · Sarah"}
            total={sideGuests.length}
            defaultOpen={s === "Nick"}
            status={sideGuests.length === 0 ? "Nog toe te voegen" : `${sInvited} uitgenodigd · ${sPresent} aanwezig`}
          >
            {sortedCats.map((c) => (
              <div key={c}>
                <div className="wp-subhead"><span>{c}</span><span>{cats[c].length}</span></div>
                <ul className="wp-guest-list">
                  {cats[c].map((g) => {
                    const isCustom = data.customGuests.some((cg) => cg.id === g.id);
                    return (
                      <li key={g.id} className="wp-guest-row">
                        <span className="wp-guest-name">{g.name}</span>
                        <span className="wp-row-r">
                          <button className={"wp-gtog" + (inv(g) ? " is-inv" : "")} onClick={() => toggleInv(g)} aria-pressed={inv(g)}>Uitgenodigd</button>
                          <button className={"wp-gtog" + (pres(g) ? " is-pres" : "")} onClick={() => togglePres(g)} aria-pressed={pres(g)}>Aanwezig</button>
                          {isCustom && <button className="wp-delx" onClick={() => setData((d) => ({ ...d, customGuests: d.customGuests.filter((cg) => cg.id !== g.id) }))} aria-label="Verwijder gast">×</button>}
                        </span>
                      </li>
                    );
                  })}
                </ul>
              </div>
            ))}
          </Collapsible>
        );
      })}

      {adding ? (
        <section className="wp-card wp-addform">
          <input className="wp-input" placeholder="Naam gast" value={name} onChange={(e) => setName(e.target.value)} />
          <div className="wp-addrow">
            <select className="wp-input" value={side} onChange={(e) => setSide(e.target.value)}>
              <option value="Nick">Van Nick</option>
              <option value="Sarah">Van Sarah</option>
            </select>
            <select className="wp-input" value={cat} onChange={(e) => setCat(e.target.value)}>
              {CAT_ORDER.map((o) => <option key={o}>{o}</option>)}
            </select>
          </div>
          <div className="wp-addrow">
            <button className="wp-btn-ghost" onClick={() => setAdding(false)}>Annuleren</button>
            <button className="wp-btn" disabled={!name.trim()} onClick={() => { setData((d) => ({ ...d, customGuests: [...d.customGuests, { id: "cg" + Date.now(), name: name.trim(), category: cat, side, inv: true, pres: false }] })); setName(""); setAdding(false); }}>Toevoegen</button>
          </div>
        </section>
      ) : (
        <button className="wp-add-btn" onClick={() => setAdding(true)}>+ Gast toevoegen</button>
      )}
    </div>
  );
}

/* ---------- Bits ---------- */

function Check() {
  return (
    <svg viewBox="0 0 16 16" width="13" height="13" fill="none" aria-hidden="true">
      <path d="M3 8.5l3 3 7-7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function ResetButton({ setData }) {
  const [confirm, setConfirm] = useState(false);
  if (confirm)
    return (
      <span className="wp-reset-confirm">
        Alles wissen?
        <button className="wp-reset-yes" onClick={() => { setData(EMPTY); setConfirm(false); }}>ja</button>
        <button className="wp-reset-no" onClick={() => setConfirm(false)}>nee</button>
      </span>
    );
  return <button className="wp-reset" onClick={() => setConfirm(true)}>reset</button>;
}

/* ============================================================
   Styles
   ============================================================ */

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=Mulish:wght@400;500;600;700&display=swap');

.wp-root{
  --paper:#fbf6f2; --paper2:#fffdfb; --ink:#3a2e2c; --muted:#8c7d75;
  --rose:#c1913f; --rose-deep:#9c7529; --sage:#5b6b57; --brass:#b08d57; --blush:#f3e3df;
  --line:#ece0d9;
  font-family:'Mulish',system-ui,sans-serif; color:var(--ink); background:var(--paper);
  min-height:100vh; max-width:520px; margin:0 auto; -webkit-font-smoothing:antialiased;
  font-feature-settings:'tnum';
}
.wp-root *{box-sizing:border-box;}
.wp-root button{font-family:inherit; cursor:pointer;}
.wp-root :focus-visible{outline:2px solid var(--rose); outline-offset:2px; border-radius:4px;}

/* Hero */
.wp-hero{position:relative; overflow:hidden; text-align:center;}
.wp-hero-floral{position:absolute; inset:0; z-index:0; background-size:cover; background-position:center; background-repeat:no-repeat;}
.wp-hero-wash{position:absolute; inset:0; z-index:1;
  background:
    radial-gradient(125% 95% at 50% 42%, rgba(251,246,242,.82) 22%, rgba(251,246,242,.5) 52%, rgba(251,246,242,.1) 100%),
    radial-gradient(120% 80% at 18% 4%, rgba(247,223,226,.4) 0%, rgba(247,223,226,0) 55%);
}
.wp-hero-body{position:relative; z-index:2; padding:32px 24px 32px;}
.wp-nav{position:relative; z-index:20; display:flex; align-items:center; justify-content:space-between; padding:10px 16px 12px; background:#fff;}
.wp-nav-logo{width:46px; height:auto; opacity:.9;}
.wp-nav-right{display:flex; align-items:center; gap:10px;}
.wp-nav-line{position:absolute; left:0; right:0; bottom:0; height:4px; background:linear-gradient(to bottom, var(--brass) 0, var(--brass) 1px, transparent 1px, transparent 3px, var(--brass) 3px, var(--brass) 4px); animation:goldGlow 7s ease-in-out infinite;}
@keyframes goldGlow{0%, 80%, 100%{filter:brightness(1); box-shadow:0 0 0 rgba(198,155,94,0);} 90%{filter:brightness(1.45) saturate(1.25); box-shadow:0 1px 9px rgba(198,155,94,.6);}}
.wp-burger{width:38px; height:38px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:4px; border:1px solid var(--line); background:var(--paper2); border-radius:10px; cursor:pointer; padding:0;}
.wp-burger span{display:block; width:18px; height:2px; background:var(--ink); border-radius:2px; transition:transform .2s ease, opacity .2s ease;}
.wp-burger.is-open span:nth-child(1){transform:translateY(6px) rotate(45deg);}
.wp-burger.is-open span:nth-child(2){opacity:0;}
.wp-burger.is-open span:nth-child(3){transform:translateY(-6px) rotate(-45deg);}
.wp-menu-back{position:fixed; inset:0; z-index:1;}
.wp-menu{position:absolute; top:calc(100% + 6px); right:14px; z-index:2; min-width:172px; background:#fff; border:1px solid var(--line); border-radius:14px; box-shadow:0 14px 34px rgba(58,46,44,.18); padding:7px; display:flex; flex-direction:column; gap:2px;}
.wp-menu-item{padding:10px 13px; border:none; background:transparent; border-radius:9px; font-size:14px; font-weight:600; color:var(--ink); text-align:left; cursor:pointer;}
.wp-menu-item:hover{background:#f4ece5;}
.wp-menu-item.is-on{background:var(--ink); color:var(--paper);}
.wp-menu-sep{height:1px; background:var(--line); margin:5px 4px;}
.wp-sprig{position:absolute; width:54px; color:var(--sage); opacity:.45; z-index:1;}
.wp-sprig-l{top:14px; left:6px; transform:rotate(-18deg);}
.wp-sprig-r{top:14px; right:6px; transform:scaleX(-1) rotate(-18deg);}
.wp-eyebrow{position:relative; z-index:2; margin:0 0 10px; font-size:11px; letter-spacing:.32em; text-transform:uppercase; color:var(--rose);}
.wp-logo{position:relative; z-index:2; display:block; margin:0 auto 6px; width:128px; height:auto;
  filter:drop-shadow(0 2px 6px rgba(58,46,44,.08));}
.wp-names{position:relative; z-index:2; margin:0; font-family:'Fraunces',serif; font-weight:500; font-size:46px; line-height:1.02; letter-spacing:-0.01em;}
.wp-names span{font-style:italic; font-weight:400; color:var(--rose);}
.wp-countdown{position:relative; z-index:2; margin:14px 0 6px; display:flex; flex-direction:column; align-items:center;}
.wp-count-num{font-family:'Fraunces',serif; font-size:38px; font-weight:600; line-height:1; color:var(--ink);}
.wp-count-label{font-size:12px; letter-spacing:.22em; text-transform:uppercase; color:var(--muted); margin-top:6px;}
.wp-date{position:relative; z-index:2; margin:8px 0 0; font-size:14px; color:var(--ink); font-weight:600; letter-spacing:.04em;}
.wp-venues{position:relative; z-index:2; margin:3px 0 0; font-size:11.5px; letter-spacing:.14em; text-transform:uppercase; color:var(--brass); font-weight:600;}
.wp-vinyl{width:38px; height:38px; padding:0; border:1px solid rgba(198,155,94,.5); border-radius:50%; background:var(--paper2); box-shadow:0 2px 7px rgba(58,46,44,.12); cursor:pointer; transition:transform .18s ease, box-shadow .18s ease;}
.wp-vinyl:hover{transform:scale(1.06);}
.wp-vinyl:active{transform:scale(.96);}
.wp-vinyl svg{width:100%; height:100%; display:block;}
.wp-vinyl-spin{transform-box:fill-box; transform-origin:center;}
.wp-vinyl.is-spinning .wp-vinyl-spin{animation:wp-spin 3s linear infinite;}
@keyframes wp-spin{to{transform:rotate(360deg);}}
.wp-intro{position:fixed; inset:0; z-index:1000; overflow:hidden; display:flex; align-items:center; justify-content:center; background:#efdcd6; animation:wpIntroBg 3s ease forwards; will-change:opacity;}
.wp-intro::after{content:""; position:absolute; inset:14px; border:1.6px solid rgba(198,155,94,.72); border-radius:16px; z-index:3; pointer-events:none;}
.wp-intro-art{position:absolute; inset:14px; z-index:0; overflow:hidden; border-radius:16px;}
.wp-if-base{position:absolute; inset:0; background-size:cover; background-position:center; background-repeat:no-repeat;}
.wp-intro-veil{position:absolute; inset:0; z-index:1; background:radial-gradient(125% 95% at 50% 42%, rgba(251,246,242,.82) 22%, rgba(251,246,242,.5) 52%, rgba(251,246,242,.1) 100%), radial-gradient(120% 80% at 18% 4%, rgba(247,223,226,.4) 0%, rgba(247,223,226,0) 55%);}
.wp-intro-mark{position:relative; z-index:2; width:150px; height:auto; filter:drop-shadow(0 4px 16px rgba(58,46,44,.26)); animation:wpIntroMark 3s ease forwards;}
@keyframes wpIntroMark{0%{opacity:0; transform:scale(.92);} 14%{opacity:1; transform:scale(1);} 44%{opacity:1; transform:scale(1);} 60%{opacity:0; transform:scale(1.05);} 100%{opacity:0;}}
@keyframes wpIntroBg{0%,64%{opacity:1;} 100%{opacity:0;}}

/* Tabs */
.wp-tabs{position:sticky; top:0; z-index:10; display:flex; gap:4px; padding:8px 12px;
  background:rgba(251,246,242,.92); backdrop-filter:blur(8px); border-bottom:1px solid var(--line);}
.wp-tab{flex:1; padding:9px 4px; border:none; background:transparent; border-radius:9px;
  font-size:13.5px; font-weight:600; color:var(--muted); transition:.18s;}
.wp-tab.is-active{background:var(--ink); color:var(--paper);}

/* Layout */
.wp-main{padding:16px 14px 8px;}
.wp-stack{display:flex; flex-direction:column; gap:14px;}
.wp-grid2{display:grid; grid-template-columns:1fr 1fr; gap:14px;}
.wp-loading{text-align:center; color:var(--muted); padding:40px 0;}

.wp-card{background:var(--paper2); border:1px solid var(--line); border-radius:18px; padding:16px;
  box-shadow:0 1px 2px rgba(58,46,44,.03);}
.wp-card-head{display:flex; align-items:baseline; justify-content:space-between; margin-bottom:10px;}
.wp-h2{font-family:'Fraunces',serif; font-size:18px; font-weight:600; margin:0;}
.wp-link{border:none; background:none; color:var(--rose); font-size:12.5px; font-weight:600;}
.wp-muted{color:var(--muted);}

/* Progress card */
.wp-progress-card{display:flex; align-items:center; gap:18px;}
.wp-ring-wrap{position:relative; width:80px; flex:none; text-align:center;}
.wp-ring{transform:rotate(-90deg); width:80px; height:80px;}
.wp-ring-bg{fill:none; stroke:var(--blush); stroke-width:7;}
.wp-ring-fg{fill:none; stroke:var(--rose); stroke-width:7; stroke-linecap:round; transition:stroke-dashoffset .6s ease;}
.wp-ring-center{position:absolute; inset:0 0 18px; display:flex; align-items:center; justify-content:center;}
.wp-ring-val{font-family:'Fraunces',serif; font-size:18px; font-weight:600;}
.wp-ring-label{display:block; font-size:10.5px; letter-spacing:.14em; text-transform:uppercase; color:var(--muted); margin-top:2px;}
.wp-progress-meta{flex:1;}
.wp-big{font-family:'Fraunces',serif; font-size:34px; font-weight:600; margin:0; line-height:1;}
.wp-overdue-pill{display:inline-block; margin-top:10px; padding:4px 10px; border-radius:99px;
  background:#f7e3e6; color:var(--rose-deep); font-size:12px; font-weight:700;}

/* Stat cards */
.wp-stat{display:flex; flex-direction:column; align-items:flex-start; gap:3px; text-align:left; width:100%;}
.wp-stat.is-warn{border-color:#e9c4cb; background:#fdf2f3;}
.wp-stat-label{font-size:11px; letter-spacing:.14em; text-transform:uppercase; color:var(--muted);}
.wp-stat-big{font-family:'Fraunces',serif; font-size:26px; font-weight:600; margin-top:2px;}
.wp-stat-sub{font-size:12px; color:var(--muted);}
.wp-stat.is-warn .wp-stat-sub{color:var(--rose-deep); font-weight:600;}

/* mini list */
.wp-mini-list{list-style:none; margin:0; padding:0; display:flex; flex-direction:column;}
.wp-mini-row{display:flex; align-items:center; gap:9px; padding:9px 0; border-top:1px solid var(--line);}
.wp-mini-row:first-child{border-top:none;}
.wp-dot{width:8px; height:8px; border-radius:50%; flex:none;}
.wp-mini-name{flex:1; font-size:14px;}
.wp-mini-date{font-size:12px; color:var(--muted); font-weight:600; flex:none;}
.wp-mini-date.is-over{color:var(--rose-deep);}
.wp-empty{padding:14px 0; color:var(--muted); text-align:center;}

/* filter bar */
.wp-filterbar{display:flex; flex-direction:column; gap:8px;}
.wp-filterrow{display:flex; gap:7px; overflow-x:auto; padding-bottom:2px; -webkit-overflow-scrolling:touch; align-items:center; scrollbar-width:none;}
.wp-filterrow::-webkit-scrollbar{display:none;}
.wp-chips{display:flex; gap:7px; overflow-x:auto; padding-bottom:2px; -webkit-overflow-scrolling:touch;}
.wp-chip{flex:none; padding:7px 14px; border:1px solid var(--line); background:var(--paper2);
  border-radius:99px; font-size:13px; font-weight:600; color:var(--muted); transition:.16s;}
.wp-chip.is-on{background:var(--ink); color:var(--paper); border-color:var(--ink);}
.wp-chip-toggle{align-self:flex-start;}
.wp-chip-toggle.is-on{background:var(--sage); border-color:var(--sage); color:#fff;}
.wp-filterrow-plain{display:flex; flex-wrap:wrap; gap:8px; align-items:center;}

/* Custom filter dropdown */
.wp-fsel{position:relative;}
.wp-fsel-btn{display:inline-flex; align-items:center; gap:8px; padding:8px 12px; border:1px solid var(--line);
  background:var(--paper2); border-radius:11px; font-size:13px; font-weight:600; color:var(--ink); transition:.16s;}
.wp-fsel-btn.is-set{border-color:var(--ink);}
.wp-fsel-btn.is-open{border-color:var(--rose);}
.wp-fsel-lab{font-size:10px; letter-spacing:.1em; text-transform:uppercase; color:var(--muted); font-weight:700;}
.wp-fsel-val{color:var(--ink);}
.wp-fsel-chev{color:#c2b1a6; font-size:17px; line-height:1; transform:rotate(90deg); transition:transform .2s ease;}
.wp-fsel-btn.is-open .wp-fsel-chev{transform:rotate(-90deg);}
.wp-fsel-backdrop{position:fixed; inset:0; z-index:40;}
.wp-fsel-menu{position:absolute; top:calc(100% + 6px); left:0; min-width:200px; max-width:min(86vw,300px);
  max-height:58vh; overflow-y:auto; z-index:50; background:var(--paper2); border:1px solid var(--line);
  border-radius:14px; box-shadow:0 12px 30px rgba(58,46,44,.16); padding:6px;}
.wp-fsel-opt{display:flex; align-items:center; justify-content:space-between; gap:10px; width:100%;
  padding:9px 11px; border:none; background:transparent; border-radius:9px; font-size:13.5px; font-weight:600;
  color:var(--ink); text-align:left;}
.wp-fsel-opt:hover{background:#f4ece5;}
.wp-fsel-opt.is-on{background:var(--ink); color:var(--paper);}
.wp-fsel-tick{font-size:12px;}

/* task groups */
.wp-group-head{display:flex; align-items:flex-start; justify-content:space-between; gap:10px; margin-bottom:8px;}
.wp-group-date{font-family:'Fraunces',serif; font-size:16px; font-weight:600; margin:0; line-height:1.2;}
.wp-group-range{display:block; font-size:11px; color:var(--muted); margin-top:2px; letter-spacing:.01em;}
.wp-group-meta{font-size:11.5px; color:var(--muted); font-weight:600; white-space:nowrap; flex:none; padding-top:2px;}
.wp-group-meta.is-over{color:var(--rose-deep);}
.wp-task-list{list-style:none; margin:0; padding:0;}
.wp-task{display:flex; gap:10px; padding:11px 0; border-top:1px solid var(--line); align-items:flex-start;}
.wp-task:first-child{border-top:none;}
.wp-check{flex:none; width:23px; height:23px; margin-top:1px; border-radius:50%;
  border:2px solid #d9cabf; background:transparent; color:#fff; display:flex; align-items:center; justify-content:center; transition:.16s;}
.wp-check.is-on{background:var(--sage); border-color:var(--sage);}
.wp-task-body{flex:1; min-width:0; cursor:pointer;}
.wp-task-name{font-size:14.5px; line-height:1.32; display:block;}
.wp-task.is-done .wp-task-name{text-decoration:line-through; color:var(--muted);}
.wp-task-meta{display:flex; flex-wrap:wrap; gap:6px; margin-top:6px; align-items:center;}
.wp-tag{font-size:10.5px; font-weight:600; padding:2px 8px; border-radius:99px; border:1px solid; letter-spacing:.01em;}
.wp-owner{font-size:10.5px; font-weight:700; padding:2px 8px; border-radius:99px;}
.wp-task-date{flex:none; margin-top:1px; font-size:11.5px; font-weight:700; color:var(--muted);
  background:#f4ece5; padding:3px 8px; border-radius:7px; white-space:nowrap; font-feature-settings:'tnum';}
.wp-task-date.is-over{background:#f7e3e6; color:var(--rose-deep);}
.wp-task.is-done .wp-task-date{opacity:.5;}
.wp-task-detail{margin:8px 0 2px; font-size:13px; color:var(--muted); line-height:1.45;
  border-left:2px solid var(--blush); padding-left:10px;}
.wp-task-edit{margin:10px 0 4px; padding:12px; background:#faf4ef; border:1px solid var(--line); border-radius:12px; display:flex; flex-direction:column; gap:7px;}
.wp-te-lab{font-size:10px; letter-spacing:.1em; text-transform:uppercase; color:var(--muted); font-weight:700; margin-bottom:-4px;}
.wp-te-input{width:100%; padding:9px 11px; border:1px solid var(--line); border-radius:9px; font-size:14px; font-family:inherit; background:var(--paper2); color:var(--ink);}
.wp-te-row{display:flex; gap:8px; align-items:center; margin-top:2px;}
.wp-te-seg{display:inline-flex; border:1px solid var(--line); border-radius:9px; overflow:hidden; background:var(--paper2); flex:none;}
.wp-te-segbtn{padding:8px 11px; border:none; background:transparent; font-size:12.5px; font-weight:600; color:var(--muted); border-right:1px solid var(--line);}
.wp-te-segbtn:last-child{border-right:none;}
.wp-te-segbtn.is-on{background:var(--ink); color:var(--paper);}
.wp-te-date{flex:1; min-width:0; padding:8px 10px; border:1px solid var(--line); border-radius:9px; font-size:13px; font-family:inherit; background:var(--paper2); color:var(--ink);}
.wp-te-del{padding:8px 14px; border:1px solid #e9c4cb; background:#fdf2f3; color:var(--rose-deep); border-radius:9px; font-size:12.5px; font-weight:700;}
.wp-te-del:hover{background:var(--rose-deep); color:#fff; border-color:var(--rose-deep);}
.wp-task-fold{display:flex; flex-direction:column; gap:8px; margin-top:8px;}
.wp-task-fold .wp-task-detail{margin:0;}
.wp-task-detail.is-empty{font-style:italic; opacity:.65; border-left-color:#e7dcd3;}
.wp-edit-btn{align-self:flex-end; padding:4px 11px; border:1px solid var(--line); background:var(--paper2); border-radius:99px; font-size:11.5px; font-weight:600; color:var(--muted); transition:opacity .15s ease, background .15s ease, color .15s ease;}
.wp-edit-btn:hover{background:var(--ink); color:var(--paper); border-color:var(--ink);}
@media (hover: hover){
  .wp-edit-btn{opacity:0;}
  .wp-task:hover .wp-edit-btn, .wp-edit-btn:focus-visible{opacity:1;}
}
.wp-te-actions{display:flex; justify-content:space-between; align-items:center; gap:8px; margin-top:4px;}
.wp-te-done{padding:8px 18px; border:none; background:var(--ink); color:var(--paper); border-radius:9px; font-size:12.5px; font-weight:700;}
.wp-te-seg-full{display:flex;}
.wp-te-seg-full .wp-te-segbtn{flex:1; text-align:center;}
.wp-modal-back{position:fixed; inset:0; z-index:200; background:rgba(58,46,44,.42); display:flex; align-items:center; justify-content:center; padding:20px; animation:wp-fade .18s ease;}
.wp-modal{width:100%; max-width:380px; max-height:88vh; overflow-y:auto; background:var(--paper2); border:1px solid var(--line); border-radius:18px; box-shadow:0 18px 50px rgba(58,46,44,.32); padding:18px; display:flex; flex-direction:column; gap:7px; animation:wp-pop .2s cubic-bezier(.3,1.1,.5,1);}
.wp-modal-head{display:flex; align-items:center; justify-content:space-between; margin-bottom:4px;}
.wp-modal-title{font-family:'Fraunces',serif; font-size:19px; color:var(--ink);}
.wp-modal-x{width:30px; height:30px; border:none; background:transparent; font-size:22px; line-height:1; color:var(--muted); cursor:pointer; border-radius:8px;}
.wp-modal-x:hover{background:#f1e7df; color:var(--ink);}
@keyframes wp-fade{from{opacity:0;}}
@keyframes wp-pop{from{opacity:0; transform:translateY(10px) scale(.98);}}

/* add */
.wp-add-btn{width:100%; padding:13px; border:1.5px dashed #d9cabf; background:transparent;
  border-radius:14px; color:var(--muted); font-weight:600; font-size:14px;}
.wp-addform{display:flex; flex-direction:column; gap:10px;}
.wp-addrow{display:flex; gap:8px;}
.wp-addrow .wp-input{flex:1;}
.wp-input{padding:11px 12px; border:1px solid var(--line); border-radius:11px; font-size:14px;
  font-family:inherit; background:var(--paper2); color:var(--ink); width:100%;}
.wp-input-sm{padding:6px 8px; width:96px; text-align:right;}
.wp-btn{padding:11px 18px; border:none; background:var(--ink); color:var(--paper); border-radius:11px; font-weight:700; font-size:14px;}
.wp-btn:disabled{opacity:.4;}
.wp-btn-ghost{padding:11px 18px; border:1px solid var(--line); background:transparent; color:var(--muted); border-radius:11px; font-weight:600;}

/* budget */
.wp-budget-hero{background:linear-gradient(180deg,#fffdfb,#fbf3f0);}
.wp-budget-hero.is-over{border-color:#e9c4cb;}
.wp-budget-top{display:flex; justify-content:space-between; align-items:flex-start;}
.wp-budget-total{font-family:'Fraunces',serif; font-size:32px; font-weight:600; margin:2px 0 0;}
.wp-target{border:1px solid var(--line); background:var(--paper2); padding:6px 11px; border-radius:99px; font-size:12px; font-weight:600; color:var(--muted);}
.wp-bar{height:9px; border-radius:99px; background:var(--blush); overflow:hidden; margin:14px 0 8px;}
.wp-bar-fill{height:100%; border-radius:99px; transition:width .5s ease;}
.wp-budget-note{margin:0; font-size:13px; color:var(--sage); font-weight:600;}
.wp-budget-note.is-over{color:var(--rose-deep);}
.wp-subtotal{font-family:'Fraunces',serif; font-weight:600; font-size:15px; color:var(--ink);}
.wp-subtotal-sub{font-family:inherit; font-size:13px; font-weight:600; color:var(--muted);}
.wp-fold-section{background:linear-gradient(180deg,#fffdfb,#faf4ef);}
.wp-fold-section > .wp-fold-head{padding-top:17px; padding-bottom:17px;}
.wp-fold-section > .wp-fold-head > .wp-fold-main .wp-fold-name{font-size:19px;}
.wp-fold-stotal{display:flex; flex-direction:column; align-items:flex-end; line-height:1.02;}
.wp-fold-stotal-lab{font-size:9px; letter-spacing:.16em; text-transform:uppercase; color:var(--muted); font-weight:700;}
.wp-fold-stotal-num{font-family:'Fraunces',serif; font-weight:600; font-size:19px; color:var(--ink); margin-top:2px;}
.wp-budget-list{list-style:none; margin:0; padding:0;}
.wp-budget-row{display:flex; justify-content:space-between; align-items:center; gap:10px; padding:9px 0; border-top:1px solid var(--line);}
.wp-budget-row:first-child{border-top:none;}
.wp-budget-name{font-size:13.5px; flex:1;}
.wp-budget-amt{border:none; background:#f6efe9; padding:5px 10px; border-radius:8px; font-weight:700; font-size:13.5px; color:var(--ink); white-space:nowrap;}
.wp-fineprint{font-size:12px; color:var(--muted); line-height:1.5; padding:0 4px;}

/* budget v2 */
.wp-card.is-over{border-color:#e9c4cb;}
.wp-summary-3{display:flex; gap:6px;}
.wp-sum-cell{flex:1; text-align:center;}
.wp-sum-num{font-family:'Fraunces',serif; font-size:23px; font-weight:600; display:block; line-height:1.1;}
.wp-sum-lab{font-size:10px; letter-spacing:.08em; text-transform:uppercase; color:var(--muted);}
.wp-bud-top{display:flex; align-items:center; justify-content:space-between; gap:10px;}
.wp-bud-room{font-size:13px; font-weight:700;}
.wp-paid-note{margin:9px 0 2px; font-size:11.5px; line-height:1.45; color:var(--muted); border-left:2px solid var(--blush); padding-left:10px;}
.wp-badge{font-size:10px; font-weight:700; letter-spacing:.05em; text-transform:uppercase; padding:3px 8px; border-radius:99px;}
.wp-badge-offerte{background:#e7efe3; color:var(--sage);}
.wp-badge-budget{background:#f4e9dd; color:var(--brass);}
.wp-paid{display:flex; flex-wrap:wrap; gap:8px 14px; align-items:center; margin-top:10px; font-size:12.5px; color:var(--muted);}
.wp-paid b{color:var(--ink); font-weight:700;}
.wp-paid-pill{border:1px solid var(--line); background:var(--paper2); padding:5px 11px; border-radius:99px; font-size:12px; font-weight:600; color:var(--muted);}
.wp-subhead{font-size:11px; letter-spacing:.1em; text-transform:uppercase; color:var(--muted); margin:16px 0 2px; display:flex; justify-content:space-between; font-weight:700;}
.wp-row-r{display:flex; align-items:center; gap:8px;}
.wp-amt{border:none; background:#f6efe9; padding:5px 10px; border-radius:8px; font-weight:700; font-size:13.5px; color:var(--ink); white-space:nowrap;}
.wp-amt.is-empty{background:transparent; border:1px dashed #d9cabf; color:var(--muted); font-weight:600;}
.wp-amt-input{width:100px; text-align:right; padding:5px 8px; border:1px solid var(--rose); border-radius:8px; font-size:13.5px; font-family:inherit;}
.wp-delx{border:none; background:none; color:#cdbcb1; font-size:18px; line-height:1; padding:0 3px;}
.wp-delx:hover{color:var(--rose-deep);}
.wp-tasklink{font-size:9px; font-weight:700; letter-spacing:.05em; text-transform:uppercase; color:var(--brass); background:#f4ece1; padding:2px 6px; border-radius:5px; margin-left:7px; vertical-align:middle;}
.wp-add-sm{border:1px dashed #d9cabf; background:transparent; border-radius:11px; padding:10px; width:100%; color:var(--muted); font-weight:600; font-size:13px; margin-top:12px;}
.wp-offerte-add{width:100%; padding:13px; border:none; background:var(--ink); color:var(--paper); border-radius:14px; font-weight:700; font-size:14px;}
.wp-tb-wrap{display:inline-flex;}
.wp-tb-pill{border:1px solid #e4d6cd; background:#f6efe9; padding:3px 10px; border-radius:99px; font-size:11px; font-weight:700; color:var(--sage);}
.wp-tb-add{border:1px dashed #d9cabf; background:transparent; padding:3px 10px; border-radius:99px; font-size:11px; font-weight:600; color:var(--muted);}
.wp-tb-input{width:84px; padding:4px 8px; border:1px solid var(--rose); border-radius:8px; font-size:12px; text-align:right; font-family:inherit;}

/* guests */
.wp-guest-summary{display:grid; grid-template-columns:repeat(3,1fr); gap:4px; text-align:center;}
.wp-gs-cell{display:flex; flex-direction:column; gap:2px; padding:4px 0;}
.wp-gs-num{font-family:'Fraunces',serif; font-size:26px; font-weight:600;}
.wp-gs-lab{font-size:10.5px; letter-spacing:.08em; text-transform:uppercase; color:var(--muted);}
.wp-guest-list{list-style:none; margin:0; padding:0;}
.wp-guest-row{display:flex; justify-content:space-between; align-items:center; padding:9px 0; border-top:1px solid var(--line);}
.wp-guest-row:first-child{border-top:none;}
.wp-guest-name{font-size:14px;}
.wp-status{border:none; padding:6px 13px; border-radius:99px; font-size:12px; font-weight:700;}
.wp-status-open{background:#f1ebe5; color:var(--muted);}
.wp-status-yes{background:#e4ece0; color:var(--sage);}
.wp-status-no{background:#f7e3e6; color:var(--rose-deep);}

/* foldout */
.wp-fold{padding:0; overflow:hidden;}
.wp-fold.is-over{border-color:#e9c4cb;}
.wp-fold-head{display:flex; align-items:center; justify-content:space-between; gap:12px; width:100%; padding:15px 16px; background:transparent; border:none; text-align:left;}
.wp-fold-main{display:flex; flex-direction:column; gap:5px; min-width:0;}
.wp-fold-titlerow{display:flex; align-items:center; gap:8px; flex-wrap:wrap;}
.wp-fold-name{font-family:'Fraunces',serif; font-size:17px; font-weight:600; color:var(--ink);}
.wp-fold-status{font-size:12px; color:var(--muted); font-weight:600;}
.wp-fold-right{display:flex; align-items:center; gap:10px; flex:none;}
.wp-chev{font-size:22px; color:#c2b1a6; transition:transform .2s ease; line-height:1; transform:rotate(90deg);}
.wp-chev.is-open{transform:rotate(-90deg);}
.wp-fold-body{padding:2px 16px 16px;}
.wp-fold-body .wp-subhead:first-child{margin-top:6px;}
.wp-fold-flush{border-top:1px solid var(--line); border-radius:0; background:transparent;}
.wp-fold-flush:first-child{border-top:none;}
.wp-fold-flush > .wp-fold-head{padding:13px 0;}
.wp-fold-flush > .wp-fold-body{padding:0 0 8px;}
.wp-fold-flush .wp-fold-name{font-size:15px;}
.wp-confirmed-block{border-top:1px solid var(--line); padding-top:6px;}
.wp-confirm-btn{flex:none; width:25px; height:25px; border:1px solid #cfe0c8; background:#eef4ea; color:var(--sage);
  border-radius:7px; font-size:13px; font-weight:800; line-height:1; display:inline-flex; align-items:center; justify-content:center;}
.wp-confirm-btn:hover{background:var(--sage); color:#fff; border-color:var(--sage);}
.wp-confirm-btn:disabled{opacity:.35;}
.wp-confirm-btn.is-undo{border-color:#e7d8cb; background:#f6efe9; color:var(--brass);}
.wp-confirm-btn.is-undo:hover{background:var(--brass); color:#fff; border-color:var(--brass);}

/* guest toggles */
.wp-gtog{border:1px solid var(--line); background:var(--paper2); padding:5px 11px; border-radius:99px; font-size:11.5px; font-weight:700; color:#bca99e;}
.wp-gtog.is-inv{background:#f4ece1; border-color:#e6d6c5; color:var(--brass);}
.wp-gtog.is-pres{background:#e4ece0; border-color:#cfe0c8; color:var(--sage);}

/* footer */
.wp-footer{display:flex; justify-content:center; align-items:center; padding:24px 18px 34px;}
.wp-footer-mark{width:44px; height:auto; opacity:.85;}
.wp-hero-rings{display:block; margin:0 auto 8px; width:98px; height:auto; filter:drop-shadow(0 3px 8px rgba(58,46,44,.14));}
.wp-clear-row{display:flex; justify-content:center; margin-top:2px;}
.wp-clear-btn{display:inline-flex; align-items:center; gap:6px; padding:8px 14px; border:1px solid var(--line); background:transparent; color:var(--muted); border-radius:12px; font-size:13px; font-weight:600; cursor:pointer;}
.wp-clear-btn:hover{color:var(--rose); border-color:var(--rose);}
.wp-clear-confirm{display:flex; align-items:center; gap:10px; flex-wrap:wrap; justify-content:center; padding:10px 14px; border:1px solid var(--line); border-radius:12px; background:var(--paper2); font-size:14px; color:var(--ink);}
.wp-btn-danger{padding:8px 16px; border:none; border-radius:10px; background:var(--rose); color:#fff; font-weight:600; font-size:14px; cursor:pointer;}
.wp-ob{position:fixed; inset:0; z-index:900; background:radial-gradient(125% 90% at 50% 26%, #ffffff 0%, var(--paper) 52%, #f1e2dc 100%); display:flex; flex-direction:column; align-items:center; justify-content:flex-start; overflow-y:auto; padding:60px 22px 36px; text-align:center;}
.wp-ob-skip2{position:absolute; top:16px; right:18px; border:none; background:transparent; color:var(--muted); font-size:14px; font-weight:600; cursor:pointer; padding:6px 8px;}
.wp-ob-hero{display:flex; flex-direction:column; align-items:center; margin:auto 0;}
.wp-ob-heart{width:150px; height:auto; margin-bottom:10px;}
.wp-heart-path{stroke-dasharray:560; stroke-dashoffset:560; animation:wpHeartDraw 1.7s ease forwards;}
.wp-heart-fill{opacity:0; transform-box:fill-box; transform-origin:center; animation:wpHeartFill 0.7s ease 1.45s forwards;}
@keyframes wpHeartDraw{to{stroke-dashoffset:0;}}
@keyframes wpHeartFill{0%{opacity:0; transform:scale(0.9);} 60%{transform:scale(1.06);} 100%{opacity:1; transform:scale(1);}}
.wp-ob-fadein{opacity:0; animation:wpObUp 0.6s ease 1.65s forwards;}
.wp-ob-fadein:nth-of-type(2){animation-delay:1.8s;}
.wp-ob-herogo{animation-delay:1.95s;}
@keyframes wpObUp{from{opacity:0; transform:translateY(12px);} to{opacity:1; transform:translateY(0);}}
.wp-ob-title{margin:0 0 6px; font-family:'Fraunces',serif; font-weight:500; font-size:30px; color:var(--ink);}
.wp-ob-sub{margin:0 0 22px; font-size:15px; line-height:1.55; color:var(--muted); max-width:320px;}
.wp-ob-stepwrap{width:100%; max-width:440px; display:flex; flex-direction:column; margin:auto 0;}
.wp-ob-dots{display:flex; gap:8px; justify-content:center; margin-bottom:26px;}
.wp-ob-dot{width:26px; height:4px; border-radius:3px; background:var(--line); transition:background .3s;}
.wp-ob-dot.is-on{background:var(--rose);}
.wp-ob-step{animation:wpObSlide 0.42s cubic-bezier(0.22,0.8,0.3,1);}
@keyframes wpObSlide{from{opacity:0; transform:translateX(26px);} to{opacity:1; transform:translateX(0);}}
.wp-ob-count{display:block; font-size:12px; font-weight:700; letter-spacing:.06em; text-transform:uppercase; color:var(--rose); margin-bottom:8px;}
.wp-ob-q{margin:0 0 20px; font-family:'Fraunces',serif; font-weight:500; font-size:26px; line-height:1.15; color:var(--ink);}
.wp-ob-hint{margin:-12px 0 16px; font-size:13px; color:var(--muted);}
.wp-ob-input{width:100%; box-sizing:border-box; padding:13px 15px; border:1px solid var(--line); border-radius:14px; font-size:16px; background:#fff; color:var(--ink); text-align:center;}
.wp-ob-input-lg{font-size:18px; padding:15px;}
.wp-ob-names{display:flex; align-items:center; gap:10px;}
.wp-ob-names .wp-ob-input{flex:1; min-width:0;}
.wp-ob-amp{font-family:'Fraunces',serif; font-style:italic; font-size:24px; color:var(--rose);}
.wp-ob-budget{display:flex; align-items:center; gap:10px;}
.wp-ob-eur{font-family:'Fraunces',serif; font-size:26px; color:var(--muted);}
.wp-ob-budget .wp-ob-input{flex:1; text-align:left;}
.wp-ob-nav{display:flex; gap:10px; margin-top:28px;}
.wp-ob-back{flex:1; padding:14px; border:1px solid var(--line); background:transparent; border-radius:14px; font-weight:600; font-size:15px; color:var(--muted); cursor:pointer;}
.wp-ob-go{flex:2; padding:14px; border:none; border-radius:14px; background:var(--ink); color:var(--paper); font-weight:600; font-size:16px; cursor:pointer;}
.wp-ob-herogo{margin-top:4px; padding:14px 40px;}
.wp-ob-card{display:flex; align-items:center; gap:14px; width:100%; text-align:left; padding:15px 16px; margin-top:12px; border:1px solid var(--line); border-radius:16px; background:#fff; cursor:pointer; transition:border-color .2s, transform .1s;}
.wp-ob-card:active{transform:scale(0.99);}
.wp-ob-card:hover{border-color:var(--brass);}
.wp-ob-cardic{flex:none; width:44px; height:44px; border-radius:12px; display:flex; align-items:center; justify-content:center; background:var(--paper); color:var(--brass);}
.wp-ob-cardtx{display:flex; flex-direction:column;}
.wp-ob-cardtx b{font-family:'Fraunces',serif; font-weight:500; font-size:17px; color:var(--ink);}
.wp-ob-cardtx i{font-style:normal; font-size:13px; color:var(--muted); margin-top:2px;}
.wp-ob-card-ai{background:linear-gradient(120deg, #fff 0%, #fbf3e5 100%); border-color:#e7cf9c;}
.wp-ob-card-ai .wp-ob-cardic{background:#f2e2c1; color:#a97f33;}
.wp-ob-file{display:inline-flex; align-items:center; justify-content:center; margin-top:20px; cursor:pointer;}
.wp-ob-busy{display:flex; align-items:center; justify-content:center; gap:10px; margin-top:20px; font-size:14px; color:var(--muted);}
.wp-spin{width:18px; height:18px; border-radius:50%; border:2.5px solid var(--line); border-top-color:var(--brass); animation:wpSpin .8s linear infinite; display:inline-block;}
@keyframes wpSpin{to{transform:rotate(360deg);}}
.wp-ob-err{margin-top:14px; font-size:13.5px; color:#b23b3b; line-height:1.4;}
.wp-ob-back-solo{margin-top:22px; align-self:center; padding:11px 26px;}
.wp-ob-tiers{display:flex; gap:8px; margin-top:16px;}
.wp-ob-tier{flex:1; display:flex; flex-direction:column; gap:2px; padding:12px 8px; border:1px solid var(--line); border-radius:13px; background:#fff; cursor:pointer;}
.wp-ob-tier b{font-family:'Fraunces',serif; font-weight:500; font-size:15px; color:var(--ink);}
.wp-ob-tier i{font-style:normal; font-size:11px; color:var(--muted); line-height:1.2;}
.wp-ob-tier.is-on{border-color:var(--brass); background:#fbf3e5;}
.wp-ob-qs{display:flex; flex-direction:column; gap:14px; margin-top:20px; text-align:left;}
.wp-ob-qrow{display:flex; flex-direction:column; gap:7px;}
.wp-ob-qlab{font-size:13px; font-weight:700; color:var(--ink); letter-spacing:.01em;}
.wp-ob-opts{display:flex; flex-wrap:wrap; gap:6px;}
.wp-ob-opt{padding:7px 12px; border:1px solid var(--line); border-radius:999px; background:#fff; font-size:12.5px; color:var(--muted); cursor:pointer;}
.wp-ob-opt.is-on{border-color:var(--brass); background:var(--ink); color:var(--paper);}
.wp-ob-ta{width:100%; box-sizing:border-box; margin-top:12px; padding:12px 14px; border:1px solid var(--line); border-radius:14px; font-size:14px; font-family:inherit; background:#fff; color:var(--ink); resize:vertical; min-height:52px;}
.wp-ob-desc{margin:2px 0 16px; font-size:14.5px; line-height:1.55; color:var(--muted);}
.wp-fold{border:1px solid var(--line); border-radius:14px; margin-top:10px; overflow:hidden; background:#fff; text-align:left;}
.wp-fold-head{display:flex; align-items:center; gap:10px; width:100%; padding:14px 16px; border:none; background:transparent; cursor:pointer;}
.wp-fold-title{flex:1; text-align:left; font-family:'Fraunces',serif; font-weight:500; font-size:16px; color:var(--ink);}
.wp-fold-meta{font-size:12px; color:var(--muted);}
.wp-fold-chev{font-size:22px; color:var(--muted); transition:transform .2s; line-height:1;}
.wp-fold-chev.is-open{transform:rotate(90deg);}
.wp-fold-body{padding:4px 16px 16px; border-top:1px solid var(--line);}
.wp-pl-sched{display:flex; flex-direction:column; gap:2px;}
.wp-pl-srow{display:flex; gap:12px; padding:6px 0; border-bottom:1px solid var(--paper);}
.wp-pl-time{flex:none; width:46px; font-weight:600; font-size:13px; color:var(--brass);}
.wp-pl-what{font-size:13.5px; color:var(--ink);}
.wp-pl-catgroup{margin-top:10px;}
.wp-pl-cat{font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.04em; margin-bottom:4px;}
.wp-pl-line{display:flex; justify-content:space-between; gap:12px; padding:5px 0; font-size:13.5px; color:var(--ink); border-bottom:1px solid var(--paper);}
.wp-pl-owner{color:var(--muted); font-size:12.5px;}
.wp-pl-total{font-weight:700; border-bottom:none; margin-top:4px;}
.wp-pl-empty{font-size:13px; color:var(--muted); padding:6px 0;}
.wp-extras-menu{min-width:210px;}
.wp-extras-del{color:#b23b3b;}
.wp-extras-danger{padding:10px 12px; border-top:1px solid var(--line);}
.wp-extras-danger>span{display:block; font-size:13px; color:var(--ink); margin-bottom:8px;}
.wp-extras-danger-row{display:flex; gap:8px; justify-content:flex-end;}
.wp-login{position:fixed; inset:0; z-index:1100; display:flex; flex-direction:column; align-items:center; justify-content:center; overflow-y:auto; padding:60px 22px 40px; background:radial-gradient(125% 90% at 50% 26%, #ffffff 0%, var(--paper) 52%, #f1e2dc 100%); text-align:center;}
.wp-login-ai{position:absolute; top:16px; right:16px; display:inline-flex; align-items:center; gap:7px; padding:8px 14px; border:1px solid #e7cf9c; border-radius:999px; background:linear-gradient(120deg,#fff,#fbf3e5); color:#a97f33; font-size:13px; font-weight:600; cursor:pointer;}
.wp-login-card{width:100%; max-width:360px; margin:auto 0; display:flex; flex-direction:column; align-items:center;}
.wp-login-rings{width:110px; height:auto; margin-bottom:6px; filter:drop-shadow(0 3px 8px rgba(58,46,44,.14));}
.wp-login-title{font-family:'Fraunces',serif; font-weight:500; font-size:40px; color:var(--ink); margin:0 0 6px;}
.wp-login-sub{font-size:14.5px; line-height:1.5; color:var(--muted); margin:0 0 22px;}
.wp-login-input{width:100%; box-sizing:border-box; margin-bottom:12px; text-align:center;}
.wp-login-go{width:100%; margin-top:4px;}
.wp-login-demo{margin-top:16px; background:none; border:none; color:var(--muted); font-size:13.5px; text-decoration:underline; cursor:pointer;}
.wp-ai-note{font-size:13.5px; line-height:1.5; color:var(--muted); margin:2px 0 14px;}
.wp-ai-provs{display:flex; gap:8px; margin-bottom:12px;}
.wp-logout{margin-top:12px; background:none; border:none; color:var(--muted); font-size:12.5px; text-decoration:underline; cursor:pointer;}

/* schema */
.wp-sched{display:flex; flex-direction:column;}
.wp-sched-phase{margin-bottom:4px;}
.wp-sched-phasehead{display:flex; align-items:center; gap:8px; font-size:12px; font-weight:700;
  letter-spacing:.06em; text-transform:uppercase; margin:16px 0 4px;}
.wp-sched-phase:first-child .wp-sched-phasehead{margin-top:0;}
.wp-sched-dot{width:8px; height:8px; border-radius:50%; flex:none;}
.wp-sched-row{display:flex; gap:10px; padding:9px 0; border-top:1px solid var(--line); align-items:flex-start;}
.wp-sched-time{flex:none; width:42px; font-family:'Fraunces',serif; font-weight:600; font-size:14px; color:var(--ink); font-feature-settings:'tnum'; padding-top:1px;}
.wp-sched-timeedit{flex:none; width:74px; font-size:12px; padding:3px 4px; border:1px solid var(--rose); border-radius:7px; font-family:inherit;}
.wp-sched-body{flex:1; min-width:0; display:flex; flex-wrap:wrap; align-items:baseline; gap:4px 8px;}
.wp-sched-what{font-size:13.5px; line-height:1.34;}
.wp-sched-markers{display:inline-flex; flex-wrap:wrap; gap:5px; align-items:center;}
.wp-mk{font-size:10.5px; font-weight:700; padding:2px 7px; border-radius:6px; white-space:nowrap; display:inline-flex; align-items:center;}
.wp-mk-travel{background:#eef0f3; color:#5a6b7a;}
.wp-mk-people{background:#f4ece1; color:var(--brass);}
.wp-mk-input{width:48px; padding:1px 4px; border:1px solid var(--rose); border-radius:5px; font-size:11px; text-align:center; font-family:inherit;}
.wp-mk-input[type=time]{width:72px;}

/* inline editable text */
.wp-editable{cursor:text; border-bottom:1px dashed #cdbcae;}
.wp-textedit{width:100%; font-family:inherit; font-size:13.5px; padding:4px 7px; border:1px solid var(--rose); border-radius:7px; line-height:1.4; resize:vertical;}

/* vendors */
.wp-vend{display:flex; flex-direction:column;}
.wp-vend-row{padding:12px 0; border-top:1px solid var(--line);}
.wp-vend-row:first-child{border-top:none;}
.wp-vend-top{display:flex; justify-content:space-between; align-items:center; gap:10px;}
.wp-vend-name{font-family:'Fraunces',serif; font-size:15px; font-weight:600;}
.wp-vend-when{font-size:11px; font-weight:700; color:var(--sage); background:#e7efe3; padding:4px 10px; border-radius:99px; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;}
.wp-vend-when .wp-mk-input{background:#fff;}
.wp-vend-rol{margin:6px 0 0; font-size:13px; color:var(--ink); line-height:1.45;}

@media (prefers-reduced-motion: reduce){
  .wp-root *{transition:none !important; animation:none !important;}
}
`;
export default function App() {
  const [uid, setUid] = useState(() => { try { return localStorage.getItem("weddy_uid"); } catch (e) { return null; } });
  const login = (u) => { try { localStorage.setItem("weddy_uid", u); } catch (e) {} setUid(u); };
  const logout = () => { try { localStorage.removeItem("weddy_uid"); } catch (e) {} setUid(null); };
  return (
    <>
      <style>{CSS}</style>
      {uid ? <Planner key={uid} uid={uid} onLogout={logout} /> : <Login onLogin={login} />}
    </>
  );
}
